def evaluasi_kuorum(n, r, w):
    if n <= 0 or not (1 <= r <= n) or not (1 <= w <= n):
        raise ValueError('Nilai N, R, W tidak valid')
    write_maj = w > (n / 2)
    overlap = (r + w) > n
    return {
        'write_majority': write_maj,
        'read_write_overlap': overlap,
        'strong_consistency': write_maj and overlap,
        'max_failed_write': n - w,
        'max_failed_read': n - r,
    }

