def query_stationery(docs, min_dim=None, max_dim=None, tag_in=None, tag_nin=None):
    hasil = []
    for d in docs:
        dims = d.get('dim_cm', [])
        tags = set(d.get('tags', []))
        if min_dim is not None and not any(x > min_dim for x in dims):
            continue
        if max_dim is not None and not any(x < max_dim for x in dims):
            continue
        if tag_in is not None and not (tags & set(tag_in)):
            continue
        if tag_nin is not None and (tags & set(tag_nin)):
            continue
        hasil.append(d['item'])
    return hasil

import copy

def apply_mongo_update(doc, update_spec):
    res = copy.deepcopy(doc)
    for k, v in update_spec.get('$set', {}).items():
        res[k] = v
    for k in update_spec.get('$unset', {}):
        res.pop(k, None)
    for old_k, new_k in update_spec.get('$rename', {}).items():
        if old_k in res:
            res[new_k] = res.pop(old_k)
    for k, v in update_spec.get('$addToSet', {}).items():
        arr = res.setdefault(k, [])
        if v not in arr:
            arr.append(v)
    return res

def run_pipeline(docs, stages):
    cur = [dict(d) for d in docs]
    for st in stages:
        op, spec = next(iter(st.items()))
        if op == '$match':
            cur = [d for d in cur if all(d.get(k) == v for k, v in spec.items())]
        elif op == '$group':
            gkey = spec['_id'][1:] if isinstance(spec['_id'], str) and spec['_id'].startswith('$') else spec['_id']
            buckets = {}
            for d in cur:
                k = d.get(gkey)
                if k not in buckets:
                    buckets[k] = {'_id': k}
                    for out_f, acc in spec.items():
                        if out_f != '_id':
                            buckets[k][out_f] = 0
                for out_f, acc in spec.items():
                    if out_f == '_id':
                        continue
                    expr = acc['$sum']
                    if expr == 1:
                        buckets[k][out_f] += 1
                    elif isinstance(expr, str) and expr.startswith('$'):
                        buckets[k][out_f] += d.get(expr[1:], 0)
            cur = list(buckets.values())
        elif op == '$sort':
            for f, direction in reversed(list(spec.items())):
                cur = sorted(cur, key=lambda d: d.get(f), reverse=(direction == -1))
        elif op == '$project':
            keep = {k for k, v in spec.items() if v == 1}
            cur = [{k: d[k] for k in keep if k in d} for d in cur]
        elif op == '$limit':
            cur = cur[:spec]
    return cur

