import hashlib

def hash_modulo_shard(key, num_shards):
    return sum(ord(c) for c in key) % num_shards

class ConsistentHashRing:
    def __init__(self, nodes_pos):
        self.ring = sorted((pos, name) for name, pos in nodes_pos.items())

    def get_node(self, key):
        pos = int(hashlib.md5(key.encode()).hexdigest(), 16) % 360
        for node_pos, name in self.ring:
            if node_pos >= pos:
                return name
        return self.ring[0][1]

