class CassandraTable:
    def __init__(self, partition_col, clustering_col):
        self.partition_col = partition_col
        self.clustering_col = clustering_col
        self.partitions = {}

    def insert(self, row):
        pkey = row[self.partition_col]
        part = self.partitions.setdefault(pkey, [])
        part.append(dict(row))
        part.sort(key=lambda r: r[self.clustering_col])

    def select(self, partition_val=None, min_cluster=None):
        if partition_val is None:
            raise ValueError('WHERE harus menyertakan partition key')
        part = self.partitions.get(partition_val, [])
        if min_cluster is None:
            return list(part)
        return [r for r in part if r[self.clustering_col] >= min_cluster]

