    def add_edge(self, src, rel_type, dst, **props):
        self.edges.append({'src': src, 'type': rel_type, 'dst': dst, 'props': props})

    def match_outgoing(self, src, rel_type=None):
        return [
            e['dst'] for e in self.edges
            if e['src'] == src and (rel_type is None or e['type'] == rel_type)
        ]

