from collections import deque

def shortest_path_bfs(graph, start, target, rel_type=None):
    if start == target:
        return [start]
    queue = deque([[start]])
    visited = {start}
    while queue:
        path = queue.popleft()
        node = path[-1]
        for nbr, rtype, _ in graph.get(node, []):
            if rel_type is not None and rtype != rel_type:
                continue
            if nbr == target:
                return path + [nbr]
            if nbr not in visited:
                visited.add(nbr)
                queue.append(path + [nbr])
    return []

def match_weighted_edges(graph, rel_type, min_weight):
    res = []
    for src, edges in graph.items():
        for dst, rtype, w in edges:
            if rtype == rel_type and w >= min_weight:
                res.append((src, dst, w))
    return sorted(res, key=lambda x: (x[0], x[1]))

