class YARNScheduler:
    def __init__(self, total_vcpu, total_ram_gb):
        self.free_vcpu = total_vcpu
        self.free_ram = total_ram_gb
        self.running = {}

    def submit_job(self, job_id, vcpu, ram_gb):
        if vcpu <= self.free_vcpu and ram_gb <= self.free_ram:
            self.free_vcpu -= vcpu
            self.free_ram -= ram_gb
            self.running[job_id] = (vcpu, ram_gb)
            return True
        return False

    def release_job(self, job_id):
        if job_id in self.running:
            vcpu, ram = self.running.pop(job_id)
            self.free_vcpu += vcpu
            self.free_ram += ram

    def available(self):
        return (self.free_vcpu, self.free_ram)

