class ReplicationCluster:
    def __init__(self, delay_ms):
        self.delay_ms = delay_ms
        self.primary = {}
        self.replica = {}
        self.pending = []

    def write(self, key, val, t_ms):
        self.primary[key] = val
        self.pending.append((t_ms + self.delay_ms, key, val))

    def _sync(self, t_ms):
        still_pending = []
        for deliver_t, k, v in sorted(self.pending, key=lambda x: x[0]):
            if deliver_t <= t_ms:
                self.replica[k] = v
            else:
                still_pending.append((deliver_t, k, v))
        self.pending = still_pending

    def read_from_replica(self, key, t_ms):
        self._sync(t_ms)
        return self.replica.get(key)

    def read_your_writes(self, key, t_ms):
        return self.primary.get(key)

