def sloppy_write(primary_nodes, alive_nodes, backup_pool, w):
    written = [n for n in primary_nodes if n in alive_nodes][:w]
    handoff = []
    for b in backup_pool:
        if len(written) >= w:
            break
        if b in alive_nodes and b not in written:
            written.append(b)
            handoff.append(b)
    return {'written_nodes': written, 'hinted_handoff': handoff, 'success': len(written) >= w}

