    return sorted(nodes)[0]

def hitung_migrasi(keys):
    mod_moved = 0
    con_moved = 0
    old_ring = [0, 120, 240]
    new_ring = [0, 120, 180, 240]
    for k in keys:
        h = int(hashlib.md5(k.encode()).hexdigest(), 16)
        if (h % 3) != (h % 4):
            mod_moved += 1
        pos = h % 360
        if _ring_owner(pos, old_ring) != _ring_owner(pos, new_ring):
            con_moved += 1
    return {'modulo_moved': mod_moved, 'consistent_moved': con_moved}

