def eval_redis_commands(commands):
    store = {}
    expires = {}
    out = []
    for cmd in commands:
        parts = cmd.split()
        op = parts[0].upper()
        if op == 'SET':
            store[parts[1]] = parts[2]
            expires.pop(parts[1], None)
            out.append('OK')
        elif op == 'GET':
            out.append(store.get(parts[1]))
        elif op == 'DEL':
            existed = parts[1] in store
            store.pop(parts[1], None)
            expires.pop(parts[1], None)
            out.append(1 if existed else 0)
        elif op == 'EXISTS':
            out.append(1 if parts[1] in store else 0)
        elif op == 'INCR':
            val = int(store.get(parts[1], 0)) + 1
            store[parts[1]] = str(val)
            out.append(val)
        elif op == 'DECR':
            val = int(store.get(parts[1], 0)) - 1
            store[parts[1]] = str(val)
            out.append(val)
        elif op == 'EXPIRE':
            if parts[1] in store:
                expires[parts[1]] = int(parts[2])
                out.append(1)
            else:
                out.append(0)
        elif op == 'TTL':
            if parts[1] not in store:
                out.append(-2)
            else:
                out.append(expires.get(parts[1], -1))
    return out

