    if not used.issubset(allowed):
        return {'valid': False, 'alasan': 'Memfilter kolom non-primary-key butuh ALLOW FILTERING/indeks'}
    if not set(partition_keys).issubset(where_eq):
        return {'valid': False, 'alasan': 'Partition key wajib disaring dengan kesetaraan (=)'}
    # Cek urutan clustering_cols tanpa lompat
    seen_gap = False
    for col in clustering_cols:
        if col in where_range:
            if seen_gap:
                return {'valid': False, 'alasan': 'Melompati clustering column sebelumnya'}
