import heapq
from collections import Counter

def rekomendasi_teman_atau_produk(purchases, target_user):
    mine = purchases.get(target_user, set())
    counts = Counter()
    for u, items in purchases.items():
        if u == target_user or not (mine & items):
            continue
        for it in items - mine:
            counts[it] += 1
    return sorted(counts.items(), key=lambda x: (-x[1], x[0]))

def rute_biaya_min(weighted_adj, start, goal):
    pq = [(0, start)]
    dist = {start: 0}
    while pq:
        cost, u = heapq.heappop(pq)
        if u == goal:
            return cost
        if cost > dist.get(u, float('inf')):
            continue
        for v, w in weighted_adj.get(u, []):
            nc = cost + w
            if nc < dist.get(v, float('inf')):
                dist[v] = nc
                heapq.heappush(pq, (nc, v))
    return -1

def deteksi_siklus_fraud(transfers, origin, min_amount, min_hops, max_hops):
    results = []
    def dfs(curr, path, visited):
        hops = len(path) - 1
        if hops >= max_hops:
            return
        for nxt, amt in transfers.get(curr, []):
            if amt < min_amount:
                continue
            if nxt == origin and (hops + 1) >= min_hops:
                results.append(path + [origin])
            elif nxt != origin and nxt not in visited:
                dfs(nxt, path + [nxt], visited | {nxt})
    dfs(origin, [origin], {origin})
    return sorted(results)

