def read_repair(replicas, key, r):
    sampled = replicas[:r]
    candidates = [rep[key] for rep in sampled if key in rep]
    if not candidates:
        return {'value': None, 'repaired_count': 0}
    best_val, best_ts = max(candidates, key=lambda vt: vt[1])
    repaired = 0
    for rep in sampled:
        if key not in rep or rep[key][1] < best_ts:
            rep[key] = (best_val, best_ts)
            repaired += 1
    return {'value': best_val, 'repaired_count': repaired}

def _match_cond(val, cond):
    if not isinstance(cond, dict):
        return val == cond
    for op, target in cond.items():
        if op == '$gte' and not (val is not None and val >= target):
            return False
        if op == '$gt' and not (val is not None and val > target):
            return False
        if op == '$lte' and not (val is not None and val <= target):
            return False
        if op == '$lt' and not (val is not None and val < target):
            return False
    return True

def run_full_pipeline(docs, stages):
    cur = [dict(d) for d in docs]
    for st in stages:
        op, spec = next(iter(st.items()))
        if op == '$match':
            cur = [d for d in cur if all(_match_cond(d.get(k), v) for k, v in spec.items())]
        elif op == '$unwind':
            f = spec[1:] if spec.startswith('$') else spec
            nxt = []
            for d in cur:
                for elem in d.get(f, []):
                    nd = dict(d)
                    nd[f] = elem
                    nxt.append(nd)
            cur = nxt
        elif op == '$group':
            gk = spec['_id'][1:] if isinstance(spec['_id'], str) and spec['_id'].startswith('$') else spec['_id']
            buckets = {}
            for d in cur:
                buckets.setdefault(d.get(gk), []).append(d)
            nxt = []
            for k, rows in buckets.items():
                rec = {'_id': k}
                for out_f, acc in spec.items():
                    if out_f == '_id':
                        continue
                    if '$sum' in acc:
                        expr = acc['$sum']
                        rec[out_f] = len(rows) if expr == 1 else sum(r.get(expr[1:], 0) for r in rows)
                    elif '$avg' in acc:
                        expr = acc['$avg']
                        vals = [r.get(expr[1:], 0) for r in rows]
                        rec[out_f] = sum(vals) / len(vals)
                nxt.append(rec)
            cur = nxt
        elif op == '$sort':
            for f, direction in reversed(list(spec.items())):
                cur = sorted(cur, key=lambda d: d.get(f), reverse=(direction == -1))
        elif op == '$project':
            keep = {k for k, v in spec.items() if v == 1}
            cur = [{k: d[k] for k in keep if k in d} for d in cur]
        elif op == '$limit':
            cur = cur[:spec]
    return cur
